    if (n > 1) cin >> a[1];
    if (n > 2) cin >> a[2];
    if (n > 3) cin >> a[3];
    if (n == 5) cin >> a[4];

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n - i - 1; ++j) {
            if (a[j] > a[j + 1]) {
                swap(a[j], a[j + 1]);
            }
        }
    }

    int t = (a[0] + a[n - 1]) >> 1;
    int left = -1, right = n;
